// 02 - Validar y normalizar
// Valida del lado del servidor, limpia los datos y genera la clave de idempotencia.
return $input.all().map(item => {
  const d = item.json;
  const limpiar = v => (v ?? '').toString().trim().replace(/\s+/g, ' ');
  const nombre  = limpiar(d['Nombre']);
  const email   = limpiar(d['Email']).toLowerCase();
  const empresa = limpiar(d['Empresa']);
  const mensaje = (d['Mensaje'] ?? '').toString().trim();

  const errores = [];
  if (nombre.length < 2) errores.push('Nombre vacío o demasiado corto');
  const emailValido = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email);
  if (!email) errores.push('Email vacío');
  else if (!emailValido) errores.push('Email con formato inválido');
  if (mensaje.length < 20) errores.push('Mensaje vacío o demasiado corto (mínimo 20 caracteres)');
  if (mensaje.length > 3000) errores.push('Mensaje demasiado largo (máximo 3000 caracteres)');

  // Huella FNV-1a de email + mensaje: detecta reenvíos idénticos (no es criptográfica).
  const base = email + '|' + mensaje.toLowerCase().replace(/\s+/g, ' ');
  let h = 0x811c9dc5;
  for (let i = 0; i < base.length; i++) { h ^= base.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  const clave = 'DD-' + h.toString(16).padStart(8, '0') + '-' + base.length;

  return { json: {
    nombre, email: emailValido ? email : '', email_recibido: email, empresa, mensaje,
    fecha_recepcion: new Date().toISOString(),
    es_valido: errores.length === 0, errores, errores_texto: errores.join('; '),
    clave_dedup: clave
  }};
});

// 12 - Armar contexto para IA
// Junta el catálogo de servicios activos (base de conocimiento) con los datos del lead.
const servicios = $input.all()
  .map(i => {
    const f = i.json.fields ?? i.json;
    return { id: i.json.id, servicio: f.Servicio, codigo: f.Codigo, descripcion: f.Descripcion,
             incluye: f.Incluye, plazo: f.Plazo_Estimado };
  })
  .filter(s => s.id && s.servicio && s.codigo);

if (servicios.length === 0) {
  throw new Error('El catálogo de servicios activos está vacío: no se puede clasificar la consulta');
}

const lead = $('02 - Validar y normalizar').first().json;
const catalogo = servicios
  .map((s, i) => `${i + 1}. ${s.servicio} | codigo: ${s.codigo} | ${s.descripcion} | incluye: ${s.incluye} | plazo orientativo: ${s.plazo}`)
  .join('\n');

return [{ json: {
  lead_id: $('06 - Crear lead (Pendiente)').first().json.id,
  nombre: lead.nombre,
  empresa: lead.empresa || '(no informada)',
  mensaje: lead.mensaje,
  catalogo_texto: catalogo,
  servicios
}}];

