// 14 - Validar clasificación
// La IA nunca avanza sin pasar por acá: JSON válido, valores permitidos, longitudes y consistencia con el catálogo.
const ctx = $('12 - Armar contexto para IA').first().json;
const r = $input.first().json;
const intento = $runIndex + 1;

// Texto devuelto por el modelo (formato del nodo Anthropic: content[].text)
const content = r.content ?? (r.message && r.message.content) ?? [];
let texto = Array.isArray(content)
  ? content.filter(c => c && c.type === 'text').map(c => c.text).join('\n')
  : (typeof content === 'string' ? content : '');
if (!texto && typeof r.text === 'string') texto = r.text;
const usage = r.usage ?? {};

// Parseo tolerante a bloques ```json
let d = null;
const limpio = texto.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
try { d = JSON.parse(limpio); } catch (e) {
  const m = limpio.match(/\{[\s\S]*\}/);
  if (m) { try { d = JSON.parse(m[0]); } catch (e2) { d = null; } }
}

const errores = [];
let servicio = null;
if (!d || typeof d !== 'object' || Array.isArray(d)) {
  errores.push('La respuesta del modelo no es un JSON válido');
} else {
  const permitidos = {
    tipo_servicio: ['sistema_excel', 'dashboard_bi', 'automatizacion_reportes', 'capacitacion', 'otro'],
    prioridad: ['alta', 'media', 'baja'],
    nivel_sugerido: ['basico', 'intermedio', 'completo'],
  };
  for (const [k, vals] of Object.entries(permitidos)) {
    if (!vals.includes(d[k])) errores.push(`${k} inválido: ${JSON.stringify(d[k])}`);
  }
  if (typeof d.resumen !== 'string' || d.resumen.trim().length < 10 || d.resumen.length > 200)
    errores.push('resumen ausente o fuera de rango (10 a 200 caracteres)');
  if (typeof d.motivo !== 'string' || d.motivo.length > 300)
    errores.push('motivo ausente o mayor a 300 caracteres');
  if (!Array.isArray(d.datos_faltantes) || d.datos_faltantes.length > 5 || d.datos_faltantes.some(x => typeof x !== 'string'))
    errores.push('datos_faltantes debe ser una lista de hasta 5 textos');
  if (d.requiere_revision_humana !== true)
    errores.push('requiere_revision_humana debe ser true');

  // Consistencia entre la clasificación y el catálogo real
  servicio = ctx.servicios.find(s => s.servicio === d.servicio_sugerido) || null;
  if (d.tipo_servicio === 'otro') {
    if (d.servicio_sugerido !== 'ninguno') errores.push('tipo_servicio "otro" exige servicio_sugerido "ninguno"');
  } else if (!servicio) {
    errores.push(`servicio_sugerido no existe en el catálogo: ${JSON.stringify(d.servicio_sugerido)}`);
  } else if (servicio.codigo !== d.tipo_servicio) {
    errores.push(`inconsistencia: "${servicio.servicio}" es ${servicio.codigo}, no ${d.tipo_servicio}`);
  }
}

// Prueba de fallo controlado (documentada en la matriz de pruebas)
if (ctx.mensaje.includes('[TEST_IA_INVALIDA]'))
  errores.push('Fallo simulado de forma controlada ([TEST_IA_INVALIDA]): se descarta la respuesta del modelo');

return [{ json: {
  valido: errores.length === 0,
  intento,
  errores,
  errores_texto: errores.length ? `Intento ${intento}: ${errores.join('; ')}` : '',
  etapa_error: 'Validación de la clasificación IA (tras reintento)',
  respuesta_cruda: texto.slice(0, 2000),
  clasificacion: d,
  servicio_id: servicio ? servicio.id : null,
  servicio_nombre: servicio ? servicio.servicio : null,
  servicio_detalle: servicio
    ? `${servicio.servicio}: ${servicio.descripcion} Incluye: ${servicio.incluye} Plazo orientativo: ${servicio.plazo}.`
    : 'Ningún servicio del catálogo aplica directamente.',
  tokens_entrada: usage.input_tokens ?? 0,
  tokens_salida: usage.output_tokens ?? 0
}}];

