// 17 - Validar borrador y generar huella
// Valida el email propuesto y calcula Hash_Borrador: la aprobación humana valdrá solo para esta versión exacta.
const prev = $('14 - Validar clasificación').last().json;
const ctx = $('12 - Armar contexto para IA').first().json;
const r = $input.first().json;

const content = r.content ?? (r.message && r.message.content) ?? [];
let texto = Array.isArray(content)
  ? content.filter(c => c && c.type === 'text').map(c => c.text).join('\n')
  : (typeof content === 'string' ? content : '');
if (!texto && typeof r.text === 'string') texto = r.text;
const usage = r.usage ?? {};

let d = null;
const limpio = texto.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
try { d = JSON.parse(limpio); } catch (e) {
  const m = limpio.match(/\{[\s\S]*\}/);
  if (m) { try { d = JSON.parse(m[0]); } catch (e2) { d = null; } }
}

const errores = [];
let asunto = '', cuerpo = '';
if (!d || typeof d !== 'object') {
  errores.push('La respuesta del modelo no es un JSON válido');
} else {
  asunto = (d.asunto ?? '').toString().trim();
  cuerpo = (d.cuerpo ?? '').toString().trim();
  if (asunto.length < 5 || asunto.length > 120) errores.push('asunto ausente o fuera de rango (5 a 120 caracteres)');
  if (cuerpo.length < 300 || cuerpo.length > 2500) errores.push('cuerpo ausente o fuera de rango (300 a 2500 caracteres)');
  const todo = asunto + '\n' + cuerpo;
  if (/\$|\bUSD\b|\bARS\b|\bpesos\b|\bd[oó]lares\b|\bprecio/i.test(todo)) errores.push('el borrador menciona precios o monedas');
  if (/\[[^\]]{1,40}\]/.test(todo)) errores.push('el borrador contiene marcadores entre corchetes');
}

// Huella FNV-1a del contenido exacto (asunto + cuerpo)
const base = asunto + '\n' + cuerpo;
let h = 0x811c9dc5;
for (let i = 0; i < base.length; i++) { h ^= base.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
const hash = 'HB-' + h.toString(16).padStart(8, '0') + '-' + base.length;

const c = prev.clasificacion || {};
return [{ json: {
  valido: errores.length === 0,
  intento: prev.intento,
  errores,
  errores_texto: errores.length ? `Borrador: ${errores.join('; ')}` : '',
  etapa_error: 'Validación del borrador IA',
  lead_id: ctx.lead_id,
  tipo_servicio: c.tipo_servicio,
  prioridad: c.prioridad,
  nivel_sugerido: c.nivel_sugerido,
  servicio_id: prev.servicio_id,
  resumen: c.resumen,
  datos_faltantes_texto: (c.datos_faltantes || []).map(x => '- ' + x).join('\n'),
  asunto,
  cuerpo,
  hash_borrador: hash,
  tokens_entrada: (prev.tokens_entrada || 0) + (usage.input_tokens ?? 0),
  tokens_salida: (prev.tokens_salida || 0) + (usage.output_tokens ?? 0)
}}];
